// geography-a: hazards, soils, nutrients, population, inequality, statistics, GIS, remote sensing, maps.
// Run: node .scratch/geography-a/diagrams/misc.mjs
// NOTE: stats/correlation-regression, gis/data-models-georeferencing, rs/system-reflectance and skills/topographic-maps are
// GENERATED by .scratch/geography-a/tables/w1a-*.mjs: re-run this script after regenerating any of them.
import { D, C, make, lab, T } from "./_h.mjs";
const G = (body, x, y) => D.group(body, { translate: [x, y] });
const smooth = (pts) => {
  let d = `M${pts[0][0]},${pts[0][1]}`;
  for (let i = 1; i < pts.length - 1; i += 1) d += ` Q${pts[i][0]},${pts[i][1]} ${(pts[i][0] + pts[i + 1][0]) / 2},${(pts[i][1] + pts[i + 1][1]) / 2}`;
  const l = pts[pts.length - 1];
  return d + ` L${l[0]},${l[1]}`;
};
const SOIL = "#e9d5b8", ROCK = "#d8d3ca", SEA = "#d6eef7";

// ---------- 1. Seismic travel times (P 6.0 km/s, S 3.5 km/s, lag 12 s)
{
  const vp = 6.0, vs = 3.5, lag = 12;
  const d = lag / (1 / vs - 1 / vp); // 100.8 km
  const w = 560, h = 400;
  const ax = D.axes({ x: [0, 150], y: [0, 45], w, h, xTicks: 25, yTicks: 5, xLabel: "Distance from the epicentre (km)", yLabel: "Travel time (s)" });
  let b = ax.frame;
  b += ax.line([[0, 0], [150, 150 / vp]], { stroke: C.blue }) + ax.line([[0, 0], [150, 150 / vs]], { stroke: C.red });
  b += lab(ax.X(150) - 6, ax.Y(150 / vp) + 34, "P waves (6.0 km/s)", { anchor: "end", fill: C.blue, size: 13 });
  b += lab(ax.X(114) - 6, ax.Y(114 / vs) + 4, "S waves (3.5 km/s)", { anchor: "end", fill: C.red, size: 13 });
  b += D.line(ax.X(d), ax.Y(d / vs) + 8, ax.X(d), ax.Y(d / vp) - 8, { stroke: C.ink, width: 1.6, arrow: true, arrowStart: true });
  b += ax.point(d, d / vp, { stroke: C.blue, r: 5 }) + ax.point(d, d / vs, { stroke: C.red, r: 5 });
  b += D.line(ax.X(d), ax.Y(d / vs), ax.X(d), ax.axisX, { stroke: C.muted, width: 1.3, dash: true });
  b += lab(ax.X(d) + 10, ax.Y((d / vs + d / vp) / 2) + 4, `S–P lag = 12 s`, { anchor: "start", size: 13 });
  b += lab(ax.X(d) - 10, ax.Y(d / vp) + 36, `Distance = ${d.toFixed(1)} km`, { anchor: "end", size: 12 });
  await make("seismic-travel-time-lag", w, h, b,
    "Travel-time graph for seismic waves: P waves at 6.0 km/s and S waves at 3.5 km/s drift further apart with distance, and a lag of 12 seconds between the first P and S arrival corresponds to a distance of about 101 km from the epicentre.",
    "Figure: P and S wave travel times and the S–P lag method for finding distance to the epicentre (worked-example speeds)",
    "hazard/earthquakes", "Distance to the epicentre from the S");
}

