  [[96, 236], [496, 236], [534, 242]].forEach(([x, y]) => { b += cloud(x, y, 0.7); });
  b += lab(100, 212, "Outer rain bands", { anchor: "middle", size: 12 }).replace("", "");
  b += D.arrow(20, 266, 160, 266, { stroke: C.red, width: 2.4 }) + D.arrow(570, 266, 420, 266, { stroke: C.red, width: 2.4 });
  b += T(92, 262, "Air spirals in", { anchor: "middle", size: 12, fill: C.red });
