  b += D.polyline([[10, 82], ...top, [570, 226], [570, 226 + pos[4][1] * k], ...[...top].reverse().map(([x, y], j) => [x, y + pos[4 - j][1] * k]), [10, 82 + 14]], { fill: SOIL, stroke: "none", close: true });
