// ---------- 4. Gersmehl diagrams (stores in kg/ha from the worked example)
{
  const eco = [
    { name: "Tropical rainforest", B: 600, L: 15, S: 120, flows: { up: 3.2, lit: 3.2, dec: 3.2, loss: 2.2 } },
    { name: "Savanna", B: 150, L: 60, S: 450, flows: { up: 1.4, lit: 1.4, dec: 1.4, loss: 1.2 } },
  ];
  const w = 580, pw = 280;
  const R = (v) => 52 * Math.sqrt(v / 600);
  let b = "";
  eco.forEach((e, i) => {
    let p = D.rect(0, 0, pw, 340, { fill: "#fff", stroke: C.grid, width: 1 }) + D.text(pw / 2, 20, e.name, { anchor: "middle", size: 14, weight: 700 });
    const Bc = [78, 110], Lc = [216, 110], Sc = [140, 245];
    const rb = R(e.B), rl = R(e.L), rs = R(e.S);
    p += D.line(Bc[0] + rb + 4, Bc[1], Lc[0] - rl - 4, Lc[1], { stroke: C.green, width: e.flows.lit, arrow: true });
    p += D.line(Lc[0] - 6, Lc[1] + rl + 4, Sc[0] + rs * 0.5, Sc[1] - rs * 0.85, { stroke: C.amber, width: e.flows.dec, arrow: true });
    p += D.line(Sc[0] - rs * 0.5, Sc[1] - rs * 0.85, Bc[0] + rb * 0.4, Bc[1] + rb * 0.9, { stroke: C.blue, width: e.flows.up, arrow: true });
    p += D.line(Sc[0] + rs + 4, Sc[1], pw - 10, Sc[1] + 6, { stroke: C.red, width: e.flows.loss, arrow: true });
    p += D.circle(Bc[0], Bc[1], rb, { fill: C.fillGreen, stroke: C.green, width: 2 }) + D.circle(Lc[0], Lc[1], rl, { fill: C.fillAmber, stroke: C.amber, width: 2 }) + D.circle(Sc[0], Sc[1], rs, { fill: SOIL, stroke: C.ink, width: 2 });
    p += D.text(Bc[0], Bc[1] - rb - 8, `Biomass (B) ${e.B}`, { anchor: "middle", size: 12, weight: 700 }) + D.text(Lc[0], Lc[1] - rl - 8, `Litter (L) ${e.L}`, { anchor: "middle", size: 12, weight: 700 }) + D.text(Sc[0], Sc[1] + rs + 16, `Soil (S) ${e.S}`, { anchor: "middle", size: 12, weight: 700 });
    p += T(150, Bc[1] - 8, "litterfall", { anchor: "middle", size: 11.5, fill: C.green });
    p += T(Lc[0] + 4, 190, "decomposition", { anchor: "middle", size: 11.5, fill: C.amber }) + T(52, 196, "uptake", { anchor: "middle", size: 11.5, fill: C.blue }) + T(pw - 12, Sc[1] - 6, "loss", { anchor: "end", size: 11.5, fill: C.red });
    const tot = e.B + e.L + e.S;
    p += T(pw / 2, 326, `Biomass is ${Math.round((100 * e.B) / tot)}% of ${tot} kg/ha`, { anchor: "middle", size: 12.5, weight: 700 });
    b += G(p, 10 + i * 290, 6);
  });
  b += D.text(290, 366, "Circle area is proportional to the nutrient store (kg per hectare).", { anchor: "middle", size: 11.5, fill: C.muted });
  b += D.text(290, 382, "Arrow width shows the relative size of each flow (qualitative).", { anchor: "middle", size: 11.5, fill: C.muted });
  await make("gersmehl-rainforest-savanna", w, 392, b,
    "Gersmehl diagrams: in the tropical rainforest most nutrients (600 of 735 kg per hectare, 82 percent) are in the large biomass circle, with a tiny litter store and rapid wide flows, while in the savanna most (450 of 660 kg per hectare, 68 percent) are in the soil circle and the flows are smaller.",
    "Figure: Gersmehl nutrient diagrams for rainforest and savanna (store sizes from the worked example; flow widths qualitative)",
    "bio/nutrient-cycles", "## The Gersmehl model");
}

// ---------- 5. Demographic transition model (schematic)
{
  const w = 580, h = 400;
  const ax = D.axes({ x: [0, 10], y: [0, 50], w, h, xTicks: [], yTicks: 10, yLabel: "Rate per 1 000 people per year", pad: { b: 70, t: 32, l: 70 }, origin: false });
  const birth = [[0, 40], [1.2, 40], [2, 40], [3.2, 39], [4.2, 31], [5.4, 18], [6.4, 13], [8, 12], [9.2, 11], [10, 10]];
  const death = [[0, 38], [1, 33], [2, 30], [3, 18], [4, 10], [5, 9], [6.4, 9], [8, 10], [9.2, 11.5], [10, 12]];
  const P = (pts) => pts.map(([x, y]) => [ax.X(x), ax.Y(y)]);
  let b = ax.frame;
  const stages = [[0, 2, "1\nHigh stationary"], [2, 4, "2\nEarly expanding"], [4, 6.4, "3\nLate expanding"], [6.4, 8.8, "4\nLow stationary"], [8.8, 10, "5\nDeclining"]];
  stages.forEach(([a, z, t], i) => {
    if (i > 0) b += D.line(ax.X(a), ax.Y(0), ax.X(a), ax.Y(50), { stroke: C.muted, width: 1.2, dash: true });
    const [num, nm] = t.split("\n");
    b += D.text(ax.X((a + z) / 2), ax.Y(0) + 20, `Stage ${num}`, { anchor: "middle", size: 12.5, weight: 700 });
    b += D.text(ax.X((a + z) / 2), ax.Y(0) + 36, nm.split(" ")[0], { anchor: "middle", size: 11 }) + D.text(ax.X((a + z) / 2), ax.Y(0) + 49, nm.split(" ").slice(1).join(" "), { anchor: "middle", size: 11 });
  });
  b += D.path_(smooth(P(birth)), { stroke: C.blue, width: 3 }) + D.path_(smooth(P(death)), { stroke: C.red, width: 3 });
  b += lab(ax.X(0.1), ax.Y(40) - 8, "Birth rate", { anchor: "start", fill: C.blue, size: 13 }) + lab(ax.X(0.1), ax.Y(38) + 28, "Death rate", { anchor: "start", fill: C.red, size: 13 });
  b += lab(ax.X(3.15), ax.Y(29), "Natural increase", { anchor: "middle", size: 12 });
  b += lab(ax.X(7.7), ax.Y(17), "Low: 10 to 15", { anchor: "middle", size: 12, fill: C.ink });
  await make("demographic-transition-model", w, h, b,
    "Demographic transition model: birth and death rates are both high in stage 1; the death rate falls first in stage 2, so the gap (natural increase) widens; in stage 3 the birth rate falls and the gap narrows; in stage 4 both are low; in stage 5 the birth rate may fall below the death rate.",
    "Figure: birth and death rates through the five stages of the demographic transition model (schematic)",
    "pop/structure-dtm", "## The demographic transition model");
}

// ---------- 6. Lorenz curve for six provinces
{
  const inc = [400, 500, 700, 900, 1200, 1800];
  const tot = inc.reduce((a, b2) => a + b2, 0);
  let cum = 0; const pts = [[0, 0]];
  inc.forEach((v, i) => { cum += v; pts.push([((i + 1) / inc.length) * 100, (cum / tot) * 100]); });
  let area = 0; for (let i = 1; i < pts.length; i += 1) area += ((pts[i][0] - pts[i - 1][0]) * (pts[i][1] + pts[i - 1][1])) / 2 / 10000;
  const gini = 1 - 2 * area; // 0.28
  const w = 560, h = 420;
  const ax = D.axes({ x: [0, 100], y: [0, 100], w, h, xTicks: 20, yTicks: 20, xLabel: "Cumulative share of provinces (%)", yLabel: "Cumulative share of income (%)" });
  let b = ax.frame;
  b += ax.area((x) => x, (x) => { const i = Math.min(inc.length - 1, Math.floor(x / (100 / inc.length))); const a0 = pts[i], a1 = pts[i + 1]; return a0[1] + ((a1[1] - a0[1]) * (x - a0[0])) / (a1[0] - a0[0]); }, [0, 100], { fill: C.fillAmber });
  b += ax.line([[0, 0], [100, 100]], { stroke: C.muted, width: 2, dash: "6 5" });
  b += ax.line(pts, { stroke: C.blue, width: 3 });
  pts.forEach(([x, y]) => { b += ax.point(x, y, { stroke: C.blue, r: 4 }); });
  b += lab(ax.X(8), ax.Y(80), "Line of perfect equality", { anchor: "start", size: 12 }) + D.line(ax.X(34), ax.Y(80) + 2, ax.X(50), ax.Y(50), { stroke: C.muted, width: 1.2 });
  b += lab(ax.X(58), ax.Y(26), "Lorenz curve (six provinces)", { anchor: "start", size: 12, fill: C.blue });
  b += lab(ax.X(58), ax.Y(15), `Shaded gap: Gini = ${gini.toFixed(2)}`, { anchor: "start", size: 13 });
  b += lab(ax.X(58), ax.Y(6), "(0 = equal, 1 = most unequal)", { anchor: "start", size: 12 });
  await make("lorenz-curve-provinces", w, h, b,
    `Lorenz curve for incomes of 400, 500, 700, 900, 1200 and 1800 US dollars in six provinces: the poorest third of provinces receive about 16 percent of income and the poorest half about 30 percent, so the curve bows below the line of equality and the Gini coefficient is ${gini.toFixed(2)}.`,
    "Figure: Lorenz curve and Gini coefficient for six provinces (worked-example incomes, illustrative)",
    "dev/regional-inequalities", "Measuring inequality between provinces");
}

// ---------- 7. Scatter with regression line (rainfall and maize yield)
{
  const X = [480, 520, 560, 610, 650, 700, 760, 820], Y = [1.1, 1.3, 1.2, 1.7, 1.9, 2.0, 2.4, 2.5];
  const n = X.length, mx = X.reduce((a, b2) => a + b2, 0) / n, my = Y.reduce((a, b2) => a + b2, 0) / n;
  const bq = X.reduce((a, x, i) => a + (x - mx) * (Y[i] - my), 0) / X.reduce((a, x) => a + (x - mx) ** 2, 0);
  const a0 = my - bq * mx;
  const f = (x) => a0 + bq * x;
  const w = 560, h = 420;
  const ax = D.axes({ x: [400, 1050], y: [0, 3.8], w, h, xTicks: 100, yTicks: 0.5, xLabel: "Seasonal rainfall (mm)", yLabel: "Maize yield (t/ha)", origin: false });
  let b = ax.frame;
  b += D.rect(ax.X(480), ax.Y(3.6), ax.X(820) - ax.X(480), ax.Y(0) - ax.Y(3.6), { fill: "#f6f2ea", stroke: "none" });
  b += ax.frame;
  b += ax.line([[480, f(480)], [820, f(820)]], { stroke: C.blue, width: 2.8 }) + ax.line([[820, f(820)], [1000, f(1000)]], { stroke: C.blue, width: 2.4, dash: "6 5" });
  X.forEach((x, i) => { b += ax.point(x, Y[i], { stroke: C.ink, fill: C.ink, r: 4.5 }); });
  b += ax.point(mx, my, { stroke: C.amber, fill: "#fff", r: 6 }) + lab(ax.X(mx) + 10, ax.Y(my) + 20, `Mean (${mx.toFixed(1)}, ${my.toFixed(2)})`, { anchor: "start", size: 12, fill: C.amber });
  b += ax.point(600, f(600), { stroke: C.green, fill: C.green, r: 5 }) + D.line(ax.X(600), ax.Y(f(600)) + 8, ax.X(640), ax.Y(0.9) - 16, { stroke: C.green, width: 1.2 }) + lab(ax.X(500), ax.Y(0.9), `600 mm: ${f(600).toFixed(2)} t/ha (interpolation)`, { anchor: "start", size: 12, fill: C.green });
  b += ax.point(1000, f(1000), { stroke: C.red, fill: "#fff", r: 6 }) + D.line(ax.X(1000), ax.Y(f(1000)) + 8, ax.X(1000), ax.Y(2.2) - 20, { stroke: C.red, width: 1.2 }) + lab(ax.X(1050), ax.Y(2.2), `1000 mm: ${f(1000).toFixed(2)} t/ha`, { anchor: "end", size: 12, fill: C.red }) + lab(ax.X(1050), ax.Y(1.8), "(extrapolation: unreliable)", { anchor: "end", size: 12, fill: C.red });
  b += lab(ax.X(404), ax.Y(3.55), `y = ${a0.toFixed(2)} + ${bq.toFixed(4)}x  (shaded band = range of the data)`, { anchor: "start", size: 12 });
  await make("scatter-regression-maize-rain", w, h, b,
    `Scatter graph of maize yield against seasonal rainfall for eight seasons with the least-squares line y = ${a0.toFixed(2)} + ${bq.toFixed(4)}x: yield rises with rainfall, the estimate of ${f(600).toFixed(2)} t/ha at 600 mm lies inside the data range (interpolation), but the estimate of ${f(1000).toFixed(2)} t/ha at 1000 mm is extrapolation and unreliable.`,
    "Figure: regression line for rainfall and maize yield, showing interpolation and extrapolation (worked-example data, illustrative)",
    "stats/correlation-regression", "Regression: rainfall and maize yield");
}

// ---------- 8. Raster and vector
{
  const w = 580, h = 400;
  const N = 10, cs = 24, ox1 = 20, ox2 = 310, oy = 56;
  const lake = [[1.5, 6.5], [3.5, 5.2], [5.0, 6.4], [5.6, 8.2], [4.0, 9.0], [2.2, 8.6]];
  const road = [[0.2, 2.0], [4.0, 4.0], [9.8, 3.0]];
  const well = [7.5, 7.4];
  const inPoly = (x, y, pg) => { let c = false; for (let i = 0, j = pg.length - 1; i < pg.length; j = i, i += 1) { const [xi, yi] = pg[i], [xj, yj] = pg[j]; if ((yi > y) !== (yj > y) && x < ((xj - xi) * (y - yi)) / (yj - yi) + xi) c = !c; } return c; };
  const dseg = (px, py, [x1, y1], [x2, y2]) => { const l2 = (x2 - x1) ** 2 + (y2 - y1) ** 2; let t = Math.max(0, Math.min(1, ((px - x1) * (x2 - x1) + (py - y1) * (y2 - y1)) / l2)); return Math.hypot(px - (x1 + t * (x2 - x1)), py - (y1 + t * (y2 - y1))); };
  const X = (ox, gx) => ox + gx * cs, Y = (gy) => oy + (N - gy) * cs; // gy up
  let b = D.text(ox1 + (N * cs) / 2, 36, "Vector: points, lines, polygons", { anchor: "middle", size: 14, weight: 700 }) + D.text(ox2 + (N * cs) / 2, 36, "Raster: grid of cells", { anchor: "middle", size: 14, weight: 700 });
  b += D.rect(ox1, oy, N * cs, N * cs, { fill: "#fff", stroke: C.ink, width: 1.5 }) + D.rect(ox2, oy, N * cs, N * cs, { fill: "#fff", stroke: C.ink, width: 1.5 });
  b += D.polyline(lake.map(([x, y]) => [X(ox1, x), Y(y)]), { fill: C.fillBlue, stroke: C.blue, width: 2.4, close: true }) + D.polyline(road.map(([x, y]) => [X(ox1, x), Y(y)]), { stroke: C.ink, width: 3 }) + D.dot(X(ox1, well[0]), Y(well[1]), { r: 5, stroke: C.red });
  // raster cells
  for (let i = 0; i < N; i += 1) for (let j = 0; j < N; j += 1) {
    const cx = i + 0.5, cy = j + 0.5;
    let cls = 0;
    if (inPoly(cx, cy, lake)) cls = 1;
    if (road.slice(1).some((p, k) => dseg(cx, cy, road[k], p) < 0.55)) cls = 2;
    if (Math.abs(cx - well[0]) < 0.5 && Math.abs(cy - well[1]) < 0.5) cls = 3;
    const fill = cls === 1 ? C.fillBlue : cls === 2 ? "#b9b4ab" : cls === 3 ? "#f4a58a" : "#fff";
    b += D.rect(X(ox2, i), Y(j + 1), cs, cs, { fill, stroke: C.grid, width: 1 });
  }
  b += D.rect(ox2, oy, N * cs, N * cs, { stroke: C.ink, width: 1.5 });
  b += D.text(ox1, 320, "Exact boundaries; one record per feature", { size: 12 }) + D.text(ox2, 320, "Edges follow the cells (stair-steps)", { size: 12 });
  b += D.text(ox2, 336, "One value per cell: blue = water, grey = road,", { size: 12 }) + D.text(ox2, 352, "red = borehole", { size: 12 });
  b += D.text(ox1, 336, "Best for roads, plots, boreholes", { size: 12 }) + D.text(ox1, 352, "(discrete features)", { size: 12 });
  b += D.text(290, 386, "Halving the cell size gives 4 times as many cells; 30 m cells to 10 m cells gives 9 times as many.", { anchor: "middle", size: 12.5, fill: C.muted });
  await make("raster-vector-comparison", w, h, b,
    "The same landscape stored two ways: the vector model keeps exact points, lines and polygons (a borehole, a road and a lake), while the raster model records one value per grid cell so the lake and road edges become stair-steps; halving the cell size gives four times as many cells.",
    "Figure: the same lake, road and borehole as vector features and as a raster grid (schematic)",
    "gis/data-models-georeferencing", "## Vector and raster compared");
}

// ---------- 9. Spectral signatures (table values)
{
  const bands = [["Blue", 0.48], ["Green", 0.56], ["Red", 0.66], ["NIR", 0.84]];
  const surf = [["Healthy maize leaves", [0.04, 0.09, 0.05, 0.52], C.green, 0.82], ["Dry bare soil", [0.12, 0.16, 0.22, 0.28], C.amber, 0.12], ["Clear water", [0.08, 0.06, 0.04, 0.02], C.blue, -0.33], ["Tarred road", [0.10, 0.11, 0.12, 0.13], C.ink, 0.04]];
  const w = 580, h = 420;
  const ax = D.axes({ x: [0.4, 0.9], y: [0, 0.6], w, h, xTicks: [], yTicks: 0.1, yLabel: "Reflectance (0 to 1)", origin: false, pad: { b: 70, t: 30, l: 70 } });
  let b = ax.frame;
  bands.forEach(([n2, wl]) => { b += D.line(ax.X(wl), ax.Y(0), ax.X(wl), ax.Y(0.6), { stroke: C.grid, width: 1 }) + D.text(ax.X(wl), ax.Y(0) + 20, n2, { anchor: "middle", size: 13 }) + D.text(ax.X(wl), ax.Y(0) + 36, `${wl} µm`, { anchor: "middle", size: 11, fill: C.muted }); });
  surf.forEach(([n2, v, col]) => { b += ax.line(bands.map(([, wl], i) => [wl, v[i]]), { stroke: col, width: 3 }); bands.forEach(([, wl], i) => { b += ax.point(wl, v[i], { stroke: col, r: 4 }); }); });
  surf.forEach(([n2, v, col, nd], i) => { const y0 = 52 + i * 22; b += D.line(ax.X(0.41), y0 - 4, ax.X(0.45), y0 - 4, { stroke: col, width: 3 }) + D.text(ax.X(0.46), y0, `${n2} (NDVI ${nd < 0 ? "−" + Math.abs(nd) : nd})`, { size: 13 }); });
  b += D.text(ax.X(0.9), ax.Y(0) + 62, "Wavelength (µm)", { anchor: "end", size: 14, weight: 600 });
  await make("spectral-signatures-ndvi", w, h, b,
    "Spectral signatures from four bands: healthy maize reflects little blue and red but 0.52 in near infrared (NDVI 0.82), dry bare soil rises steadily from 0.12 to 0.28 (NDVI 0.12), a tarred road is low and flat (0.10 to 0.13), and clear water is dark and falls to 0.02 in near infrared (NDVI minus 0.33).",
    "Figure: reflectance of maize, soil, water and a tarred road in four bands (worked-example values, illustrative)",
    "rs/system-reflectance", "## Spectral signatures");
}

// ---------- 10. Intervisibility profile
{
  const w = 560, h = 400;
  const ax = D.axes({ x: [0, 6], y: [1080, 1190], w, h, xTicks: 1, yTicks: 20, xLabel: "Distance from A (km)", yLabel: "Height (m)", origin: false, yFormat: (v) => String(v) });
  const terr = [[0, 1120], [0.8, 1128], [1.7, 1146], [2.4, 1162], [3, 1170], [3.7, 1155], [4.6, 1125], [5.4, 1108], [6, 1100]];
  let b = ax.frame;
  b += D.polyline([...terr.map(([x, y]) => [ax.X(x), ax.Y(y)]), [ax.X(6), ax.Y(1080)], [ax.X(0), ax.Y(1080)]], { fill: C.fillGrey, stroke: "none", close: true });
  b += D.polyline(terr.map(([x, y]) => [ax.X(x), ax.Y(y)]), { stroke: C.ink, width: 2.8 });
  b += D.line(ax.X(0), ax.Y(1120), ax.X(6), ax.Y(1100), { stroke: C.red, width: 2.2, dash: "6 5" });
  b += ax.point(0, 1120, { stroke: C.blue, r: 6 }) + ax.point(6, 1100, { stroke: C.blue, r: 6 }) + ax.point(3, 1170, { stroke: C.ink, r: 5 }) + ax.point(3, 1110, { stroke: C.red, r: 4 });
  b += lab(ax.X(0) + 8, ax.Y(1120) - 12, "A 1120 m", { anchor: "start", size: 13, fill: C.blue }) + lab(ax.X(6) - 8, ax.Y(1100) + 28, "B 1100 m", { anchor: "end", size: 13, fill: C.blue });
  b += lab(ax.X(3) + 10, ax.Y(1170) - 4, "Ridge 1170 m", { anchor: "start", size: 13 });
  b += lab(ax.X(0.2), ax.Y(1100) + 8, "Line of sight (dashed): 1110 m at 3 km", { anchor: "start", size: 12, fill: C.red });
  b += D.line(ax.X(3), ax.Y(1170), ax.X(3), ax.Y(1110), { stroke: C.ink, width: 1.6, arrow: true, arrowStart: true }) + lab(ax.X(3) - 8, ax.Y(1140) + 6, "60 m above", { anchor: "end", size: 12 });
  await make("intervisibility-profile", w, h, b,
    "Intervisibility profile from station A (1120 m) to station B (1100 m), 6 km apart: the straight line of sight has fallen to 1110 m at 3 km, but the ridge there is 1170 m, 60 m higher, so it blocks the view and B is not visible from A.",
    "Figure: line of sight from A to B and the blocking ridge (values from the worked example; terrain shape schematic)",
    "skills/topographic-maps", "Intervisibility along a line");
}
